-- Venue Live Guest "Wedding Istana Joseon". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara joseon), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'joseon', 'Wedding Istana Joseon', 'joseon', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 144, 'center 38%',
  $t${"name":"Istana Joseon","orn":"diamond","ui":{"ivory":"#FBF3EA","white":"#FFFFFF","soft":"#F1DCD2","soft2":"#D7A93B","accent":"#9B1C2E","deep":"#27315F","ink":"#27315F","mute":"#8A6A70","line":"#EAD3C6","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F8ECE0","ink":"#27315F","accent":"#9B1C2E","gold":"#D7A93B","leaf":"#F1DCD2","hbg":"rgba(251,243,234,.94)","hline":"#D7A93B","motif":"diamond"},"hud":{"bg":"rgba(39,49,95,.9)","acc":"#F2D27A","on":"#27315F"},"scr":{"wine":"#27315F","veil":"251,243,234"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'joseon');
